import{_ as e}from"./chunks/files.B17OUyrr.js";import{_ as t,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"ファイルを比較する","description":"2 つのファイルを並べて開き、色分けされた変更を読み、移動しながら編集や共有を行います。","frontmatter":{"title":"ファイルを比較する","description":"2 つのファイルを並べて開き、色分けされた変更を読み、移動しながら編集や共有を行います。"},"headers":[],"relativePath":"ja/guide/files.md","filePath":"ja/guide/files.md","lastUpdated":1794296122000}'),s={name:"ja/guide/files.md"};function l(n,a,d,c,p,h){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="ファイルを比較する" tabindex="-1">ファイルを比較する <a class="header-anchor" href="#ファイルを比較する" aria-label="Permalink to &quot;ファイルを比較する&quot;">​</a></h1><p>多くの方が最初に使う画面です。同じファイルの 2 つのバージョンを並べ、 違いがすべて印で示されます。</p><img src="'+e+'" alt="色分けされた変更が表示された 2 つのテキストファイル" class="guide-shot"><h2 id="_2-つのファイルを開く" tabindex="-1">2 つのファイルを開く <a class="header-anchor" href="#_2-つのファイルを開く" aria-label="Permalink to &quot;2 つのファイルを開く&quot;">​</a></h2><p><strong>ファイル → 開く</strong>を使うか、2 つのファイルを qDiff のウィンドウにドラッグする だけです。3 つのバージョンを突き合わせたい場合は、3 つ目のペインを追加できます。 色のルールは同じです。最近の比較は、次回のためにウェルカム画面に残ります。</p><h2 id="色の意味" tabindex="-1">色の意味 <a class="header-anchor" href="#色の意味" aria-label="Permalink to &quot;色の意味&quot;">​</a></h2><ul><li><strong>淡い赤</strong> —— こちら側の内容が削除された、または古いバージョンに属することを 示します。</li><li><strong>淡い緑</strong> —— 内容が追加された、または新しいバージョンに属することを示します。</li><li><strong>行の中の濃い色</strong> —— 正確にどの語が変わったかを示します。1 語だけの変更が、 行全体の色の中に埋もれてしまうことはありません。</li></ul><p>両側は連動してスクロールするので、2 つのバージョンは常に同じ行に揃います。</p><h2 id="変更箇所を移動する" tabindex="-1">変更箇所を移動する <a class="header-anchor" href="#変更箇所を移動する" aria-label="Permalink to &quot;変更箇所を移動する&quot;">​</a></h2><p>テキストの横にある細いマップをクリックすると、ファイル内のどこへでも跳べます。 前へ／次へボタン（キーボードショートカットもあります）で、変更を 1 つずつ たどることもできます。マップは長い文書の中での現在位置も示します。</p><h2 id="その場で修正する" tabindex="-1">その場で修正する <a class="header-anchor" href="#その場で修正する" aria-label="Permalink to &quot;その場で修正する&quot;">​</a></h2><p>どちらの側でも編集と取り消しができます。それぞれの変更について、比較画面から 直接、反対側へコピーしたり、置換したり、削除したりできます。別のエディタを 開く必要はありません。終わったら、いつもどおり保存してください。</p><div class="tip custom-block"><p class="custom-block-title">画像として共有する</p><p>変更を選んで画像として書き出すと、きれいな 2 段組みの画像になります。 メッセージやレビューにそのまま貼り付けられます。書き出した画像にマークは 一切付きません。</p></div><p>次は<a href="./folders.html">フォルダ全体を比較する</a>方法へ。</p>',14)])])}const m=t(s,[["render",l]]);export{f as __pageData,m as default};
